mkdir -p /workspace/probes && cat > /workspace/probes/cli.mjs <<'EOF'
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
const EXE = '/workspace/dataset/test16_executable';
const src = process.argv[2];
const cases = JSON.parse(readFileSync(src, 'utf8'));
const out = [];
for (const c of cases) {
  const argv = Array.isArray(c) ? c : c.argv;
  const opts = { encoding: 'buffer', maxBuffer: 1 << 28 };
  if (!Array.isArray(c)) {
    if (c.cwd) opts.cwd = c.cwd;
    if (c.env) opts.env = { ...process.env, ...c.env };
    if (c.exe) { /* handled below */ }
  }
  const exe = (!Array.isArray(c) && c.exe) ? c.exe : EXE;
  const r = spawnSync(exe, argv, opts);
  out.push({
    argv,
    code: r.status,
    signal: r.signal ?? null,
    stdout: (r.stdout ?? Buffer.alloc(0)).toString('utf8'),
    stderr: (r.stderr ?? Buffer.alloc(0)).toString('utf8'),
    stdout_len: (r.stdout ?? Buffer.alloc(0)).length,
    stderr_len: (r.stderr ?? Buffer.alloc(0)).length,
    spawn_error: r.error ? String(r.error.message) : undefined,
  });
}
process.stdout.write(JSON.stringify(out, null, 1) + '\n');
EOF
echo ok
